#include <unordered_map>

#include <opencv2/core/persistence.hpp>

#include "rmvlpara/camera/opt_camera.h"

namespace rm::para
{


bool OptCameraParam::load(const std::string &path)
{
    cv::FileStorage fs(path, cv::FileStorage::READ);
    if (!fs.isOpened())
        return false;
    cv::FileNode node;

    node = fs["exposure"];
    node.isNone() ? void(0) : (node >> exposure);
    node = fs["gamma"];
    node.isNone() ? void(0) : (node >> gamma);
    node = fs["contrast"];
    node.isNone() ? void(0) : (node >> contrast);
    node = fs["gain"];
    node.isNone() ? void(0) : (node >> gain);
    node = fs["b_gain"];
    node.isNone() ? void(0) : (node >> b_gain);
    node = fs["g_gain"];
    node.isNone() ? void(0) : (node >> g_gain);
    node = fs["r_gain"];
    node.isNone() ? void(0) : (node >> r_gain);
    node = fs["handle_info"];
    node.isNone() ? void(0) : (node >> handle_info);

    return true;
}

} // rm::para
